<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/includes/admin_auth.php';
require_once dirname(__DIR__) . '/includes/resources_video_data.php';
require_once __DIR__ . '/_layout.php';
require_once __DIR__ . '/_media_picker.php';

$dbError = null;
$pdo = web_db($dbError);
if (!$pdo) { header('Location: login.php'); exit; }
web_migrate($pdo);
artdon_resource_video_seed($pdo);
$user = web_require_admin($pdo);
$mainCats = artdon_resource_video_main_categories();
$subCats = artdon_resource_video_sub_categories();
$productSubCats = $subCats;
unset($productSubCats['all-products']);
$q = trim((string)($_GET['q'] ?? ''));
$main = trim((string)($_GET['main'] ?? ''));
$sub = trim((string)($_GET['sub'] ?? ''));
$isNew = isset($_GET['new']);
$page = max(1, (int)($_GET['page'] ?? 1));
$perPage = 20;
$where=[];$params=[];
if($q!==''){$where[]='(title LIKE ? OR description LIKE ?)';$params[]="%$q%";$params[]="%$q%";}
if($main!==''&&isset($mainCats[$main])){$where[]='main_category=?';$params[]=$main;}
if($sub!==''&&isset($productSubCats[$sub])){$where[]='main_category=?';$params[]='product';$where[]='sub_category=?';$params[]=$sub;}
$whereSql=$where?' WHERE '.implode(' AND ',$where):'';
$count=$pdo->prepare("SELECT COUNT(*) FROM web_resource_videos$whereSql");$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$stmt=$pdo->prepare("SELECT * FROM web_resource_videos$whereSql ORDER BY sort_order ASC,id ASC LIMIT $perPage OFFSET $offset");$stmt->execute($params);$rows=$stmt->fetchAll()?:[];
$items=array_map(static fn(array $r):array=>['id'=>(int)$r['id'],'title'=>(string)$r['title'],'description'=>(string)$r['description'],'main_category'=>(string)$r['main_category'],'sub_category'=>(string)$r['sub_category'],'source_type'=>(string)$r['source_type'],'video_url'=>(string)$r['video_url'],'cover_image'=>(string)$r['cover_image'],'cover_alt'=>(string)$r['cover_alt'],'duration'=>(string)$r['duration'],'publish_date'=>(string)$r['publish_date'],'seo_title'=>(string)($r['seo_title']??''),'seo_description'=>(string)($r['seo_description']??''),'seo_keywords'=>(string)($r['seo_keywords']??''),'sort_order'=>(int)$r['sort_order'],'is_active'=>(int)$r['is_active']===1,'is_featured'=>(int)$r['is_featured']===1],$rows);
$currentId=$isNew ? 0 : (int)($_GET['id']??($items[0]['id']??0));
$current=['id'=>0,'title'=>'','description'=>'','main_category'=>'product','sub_category'=>'track-lights','source_type'=>'youtube','video_url'=>'','cover_image'=>'','cover_alt'=>'','duration'=>'','publish_date'=>date('Y-m-d'),'seo_title'=>'','seo_description'=>'','seo_keywords'=>'','sort_order'=>10,'is_active'=>true,'is_featured'=>false];
if(!$isNew){foreach($items as $item){if($item['id']===$currentId){$current=$item;break;}}}
if(!$isNew&&$currentId>0&&(int)$current['id']===0){$one=$pdo->prepare('SELECT * FROM web_resource_videos WHERE id=? LIMIT 1');$one->execute([$currentId]);$r=$one->fetch();if($r)$current=['id'=>(int)$r['id'],'title'=>(string)$r['title'],'description'=>(string)$r['description'],'main_category'=>(string)$r['main_category'],'sub_category'=>(string)$r['sub_category'],'source_type'=>(string)$r['source_type'],'video_url'=>(string)$r['video_url'],'cover_image'=>(string)$r['cover_image'],'cover_alt'=>(string)$r['cover_alt'],'duration'=>(string)$r['duration'],'publish_date'=>(string)$r['publish_date'],'seo_title'=>(string)($r['seo_title']??''),'seo_description'=>(string)($r['seo_description']??''),'seo_keywords'=>(string)($r['seo_keywords']??''),'sort_order'=>(int)$r['sort_order'],'is_active'=>(int)$r['is_active']===1,'is_featured'=>(int)$r['is_featured']===1];}
function rv_admin_url(string $p):string{$p=trim($p);if($p==='')return'';return preg_match('#^(?:https?:)?//#i',$p)||str_starts_with($p,'data:')?$p:'../'.ltrim($p,'/');}
function rv_img(string $p):string{$u=rv_admin_url($p);return $u!==''?'<img src="'.web_e($u).'" alt="">':'<span>No image</span>';}
admin_page_start('Resources Videos 管理','resources_videos',$user);admin_notice();
?>
