pen data-media-type="video" data-media-usage="videos">从媒体库选择</button><button type="button" class="admin-button-secondary" data-media-clear>清空</button></div><input type="file" name="video_upload" accept="video/mp4,video/webm,video/quicktime"></div><div class="field"><span>封面图</span><div class="rv-media-row"><input class="media-path-input" name="cover_image" value="<?= web_e($current['cover_image']) ?>"><button type="button" class="admin-button-secondary" data-media-open data-media-type="image" data-media-usage="articles">从媒体库选择</button><button type="button" class="admin-button-secondary" data-media-clear>清空</button></div><input type="file" name="cover_upload" accept="image/*"><figure class="media-field-preview"><?= rv_img($current['cover_image']) ?></figure></div><label class="field"><span>封面 ALT</span><input name="cover_alt" value="<?= web_e($current['cover_alt']) ?>"></label><div class="rv-two"><label class="field"><span>发布时间</span><input name="publish_date" value="<?= web_e($current['publish_date']) ?>"></label><label class="field"><span>排序</span><input type="number" name="sort_order" value="<?= (int)$current['sort_order'] ?>"></label></div><label class="field"><span>SEO Title</span><input name="seo_title" value="<?= web_e($current['seo_title']) ?>"></label><label class="field"><span>SEO Description</span><textarea name="seo_description" rows="3"><?= web_e($current['seo_description']) ?></textarea></label><label class="field"><span>SEO Keywords</span><textarea name="seo_keywords" rows="2"><?= web_e($current['seo_keywords']) ?></textarea></label><label class="field rv-check"><span>状态</span><input type="checkbox" name="is_active" value="1" <?= $current['is_active']?'checked':'' ?>> 启用</label><label class="field rv-check"><span>推荐</span><input type="checkbox" name="is_featured" value="1" <?= $current['is_featured']?'checked':'' ?>> 推荐 / Popular</label><div class="rv-actions"><a class="admin-button-secondary" href="../resources-videos.php" target="_blank" rel="noopene