<script>(function(){var layer=document.querySelector('[data-rv-layer]'),mainSelect=document.querySelector('[data-main-category]'),subField=document.querySelector('[data-product-subcategory-field]');function syncSub(){if(subField&&mainSelect)subField.hidden=mainSelect.value!=='product';}function open(){if(layer){syncSub();layer.hidden=false;document.body.classList.add('admin-modal-open');}}function close(){if(layer){layer.hidden=true;document.body.classList.remove('admin-modal-open');}}if(mainSelect)mainSelect.addEventListener('change',syncSub);document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('[data-rv-open]')){open();return;}if(e.target.closest&&e.target.closest('[data-rv-close]')){close();return;}});syncSub();if(new URLSearchParams(location.search).get('new')==='1')open();})();</script>
